import heapq

def match(orders):
    buy_heap = []   # max-heap via negative price: (-price, arrival, id)
    sell_heap = []  # min-heap: (price, arrival, id)
    book = {}       # id -> {'side','price','qty','arrival'}
    trades = []

    for idx, order in enumerate(orders):
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            heap = sell_heap
            while remaining > 0 and heap:
                sprice, arrival, sid = heap[0]
                if sid not in book:
                    heapq.heappop(heap)
                    continue
                cur_price = book[sid]['price']
                if price is not None and cur_price > price:
                    break
                heapq.heappop(heap)
                sqty = book[sid]['qty']
                trade_qty = min(remaining, sqty)
                trades.append([oid, sid, cur_price, trade_qty])
                remaining -= trade_qty
                sqty -= trade_qty
                if sqty > 0:
                    book[sid]['qty'] = sqty
                    heapq.heappush(heap, (cur_price, arrival, sid))
                else:
                    del book[sid]
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'arrival': idx}
                heapq.heappush(buy_heap, (-price, idx, oid))

        else:  # sell
            heap = buy_heap
            while remaining > 0 and heap:
                neg_price, arrival, bid = heap[0]
                if bid not in book:
                    heapq.heappop(heap)
                    continue
                cur_price = book[bid]['price']
                if price is not None and cur_price < price:
                    break
                heapq.heappop(heap)
                bqty = book[bid]['qty']
                trade_qty = min(remaining, bqty)
                trades.append([bid, oid, cur_price, trade_qty])
                remaining -= trade_qty
                bqty -= trade_qty
                if bqty > 0:
                    book[bid]['qty'] = bqty
                    heapq.heappush(heap, (-cur_price, arrival, bid))
                else:
                    del book[bid]
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'arrival': idx}
                heapq.heappush(sell_heap, (price, idx, oid))

    return trades

